using UnityEngine;using UnityEditor;using System;using System.Reflection;using System.IO;
public static class ValidateTrikeCargo {public static string Main(){GameObject copy=null,fixture=null,sack=null;int checks=0;void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}void Set(object target,string name,object value)=>target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(target,value);
try{copy=UnityEngine.Object.Instantiate(UnityEngine.Object.FindFirstObjectByType<TrikeController>().GetComponent<MotorollerController>().gameObject,new Vector3(10000,0,10000),Quaternion.identity);var bike=copy.GetComponent<BicycleController>();fixture=new GameObject("Isolated cargo handler");fixture.SetActive(false);var camera=new GameObject("Camera").AddComponent<Camera>();camera.enabled=false;camera.transform.SetParent(fixture.transform,false);camera.transform.localPosition=Vector3.up*1.1f;var player=fixture.AddComponent<PlayerController>();player.characterCamera=camera;player.enabled=false;var rider=fixture.AddComponent<PlayerBicycleInteraction>();rider.player=player;
var bags=fixture.AddComponent<BagInteraction>();bags.enabled=false;var carry=new GameObject("Carry anchor").transform;carry.SetParent(fixture.transform,false);var tool=new GameObject("Inactive fixture shovel");tool.transform.SetParent(fixture.transform);tool.SetActive(false);var shovel=tool.AddComponent<ShovelTool>();Set(bags,"shovel",shovel);Set(bags,"carryAnchor",carry);Set(bags,"viewCamera",camera);
fixture.transform.position=new Vector3(9998.2f,0,10000);fixture.transform.rotation=Quaternion.Euler(0,90,0);fixture.SetActive(true);Physics.SyncTransforms();rider.Tick(true);Check(rider.bicycle==bike,"Aim selects Motoroller even without serialized bicycle reference");
sack=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/GrainPrototype/Grains/Sorting Sack.prefab"));var bag=sack.GetComponent<GrainContainer>();Set(bag,"kilograms",bag.CapacityKg);typeof(GrainContainer).GetMethod("ApplyFill",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(bag,null);sack.GetComponent<SackController>().Close=1;
var take=typeof(BagInteraction).GetMethod("Take",BindingFlags.Instance|BindingFlags.NonPublic);Check((bool)take.Invoke(bags,new object[]{bag}),"Pick up full test bag");float mass=bag.Kilograms;Check(rider.TryLoadBag(),"Secure bag to Motoroller");Check(bike.HasCargo(bag.transform)&&!bags.IsCarrying,"Transfer carry ownership");Check(bag.Kilograms==mass,"Cargo mass preserved");Check(bike.FreeCargoSlot()!=null&&bike.FreeCargoSlot()!=bag.transform.parent,"Next empty bed slot available");
bike.SetRidden(true);Check(!bag.GetComponent<Collider>().enabled,"Cargo collider disabled while riding");bike.SetRidden(false);Check(bag.GetComponent<Collider>().enabled,"Cargo collider restored");Check((bool)take.Invoke(bags,new object[]{bag}),"Retrieve bag from Motoroller");Check(bike.FreeCargoSlot()!=null,"Rack available again");Check(bags.TryStow(bike.FreeCargoSlot()),"Restow bag");string result="PASS: "+checks+" Trike targeting/cargo checks.";File.WriteAllText("output/Trike/cargo-validation.txt",result);return result;
}finally{if(sack)UnityEngine.Object.DestroyImmediate(sack);if(fixture)UnityEngine.Object.DestroyImmediate(fixture);if(copy)UnityEngine.Object.DestroyImmediate(copy);}}}


